import frappe
from frappe.model.document import Document

class PayProvisionSettlement(Document):
    def before_save(self):
        # --- from script: Save Provision Decompte (exec fallback) ---
        script = "start_date = frappe.utils.getdate(doc.pay_start_date)\n end_date = frappe.utils.getdate(doc.pay_end_date)\n \n # Calculer le nombre de jours entre les deux dates\n difference_totale = frappe.utils.date_diff(end_date, start_date)\n #frappe.msgprint(f\"Diff\u00e9rence totale en jours Premier : {difference_totale}\")\n \n # Calcul par ann\u00e9e\n annee_en_cours = start_date.year\n jours_par_annee = {}\n while annee_en_cours <= end_date.year:\n  # Date de d\u00e9but de l'ann\u00e9e en cours\n  if annee_en_cours == start_date.year :\n  date_debut_annee = start_date\n  else :\n  date_debut_annee = frappe.utils.getdate(f\"{annee_en_cours}-01-01\")\n  # Date de fin de l'ann\u00e9e en cours ou date de fin si on y est\n  date_fin_annee = min(frappe.utils.getdate(f\"{annee_en_cours + 1}-01-01\"), end_date)\n  \n  # Calcul des jours pour l'ann\u00e9e en cours\n  jours_annee = frappe.utils.date_diff(date_fin_annee,date_debut_annee)\n  jours_par_annee[annee_en_cours] = jours_annee\n  \n  annee_en_cours = annee_en_cours + 1\n \n # V\u00e9rification de la pay_sum des jours par ann\u00e9e\n somme_jours_par_annee = sum(jours_par_annee.values())\n \n # Affichage des r\u00e9sultats par ann\u00e9e\n #frappe.msgprint(f\"Jours par ann\u00e9e :\")\n \n \n Query = \"\"\"\n select * from `tabPay Provision Settlement Preparation` where pay_settlement_period = %s and employee_type = %s and docstatus = 1\n \n \"\"\"\n resultats = frappe.db.sql(Query,(doc.pay_settlement_period, doc.employment_type), as_dict = True )\n #frappe.msgprint(f\"Bien reconnu Net_Paye ==== {Net_Paye}, NbreJourPeriode ==== {NbreJourPeriode}, NombreJourAnn ==== {NombreJourAnn}\")\n for Preparation in resultats:\n # Mise \u00e0 pay_day des ann\u00e9es de pay_provision pour l'employ\u00e9\n  #nmbr = 0\n  montant_list = []\n  for pay_year, jours in jours_par_annee.items():\n  \n  #nmbr = nmbr + 1\n  pay_amount = (float(Preparation.pay_net_payable) / somme_jours_par_annee) * jours\n  montant_list.append(pay_amount)\n  #frappe.msgprint(f\"Num\u00e9ro : {Preparation.employee} NET ==> {Preparation.pay_net_payable} ==> {pay_year}: {jours} jours ==> Montant : {pay_amount}\")\n  \n  Query = \"\"\"\n  select * from `tabPay Settlement Year Detail` WHERE pay_provision_period = %s AND employee = %s\n  \n  \"\"\"\n  resultats_find = frappe.db.sql(Query,(Preparation.pay_settlement_period, Preparation.employee), as_dict = True )\n  \n  if resultats_find :\n  \n  #frappe.msgprint(f\"Num\u00e9ro : {nmbr} ==> {pay_year}: {jours} jours ==> Montant : {pay_amount}\")\n  #je = frappe.get_doc('Pay Settlement Year Detail', {'pay_provision_period':Preparation.pay_settlement_period})\n  #je.db_set('docstatus', 0, commit=True)\n  #je.delete()\n  log(\"pay_find\")\n  \n  else :\n  new_details = frappe.new_doc(\"Settlement Year Detail\")\n  new_details.update({\n  \"employee\": Preparation.employee,\n  \"employee_name\": Preparation.employee_name,\n  \"pay_year_1\": montant_list[0] if len(montant_list) > 0 else 0,\n  \"pay_year_2\": montant_list[1] if len(montant_list) > 1 else 0,\n  \"pay_year_3\": montant_list[2] if len(montant_list) > 2 else 0,\n  \"pay_year_4\": montant_list[3] if len(montant_list) > 3 else 0,\n  \"pay_year_5\": montant_list[4] if len(montant_list) > 4 else 0,\n  \"pay_year_6\": montant_list[5] if len(montant_list) > 5 else 0,\n  \"pay_year_7\": montant_list[6] if len(montant_list) > 6 else 0,\n  \"pay_year_8\": montant_list[7] if len(montant_list) > 7 else 0,\n  \"pay_year_9\": montant_list[8] if len(montant_list) > 8 else 0,\n  \"pay_year_10\": montant_list[9] if len(montant_list) > 9 else 0,\n  \"pay_year_11\": montant_list[10] if len(montant_list) > 10 else 0,\n  \"pay_year_12\": montant_list[11] if len(montant_list) > 11 else 0,\n  \"pay_year_13\": montant_list[12] if len(montant_list) > 12 else 0,\n  \"pay_year_14\": montant_list[13] if len(montant_list) > 13 else 0,\n  \"annee_o\": montant_list[14] if len(montant_list) > 14 else 0,\n  \"pay_provision_period\" : Preparation.pay_settlement_period\n  })\n  doc.append(\"details_annees_decompte\", new_details)\n  #doc.save()\n  \n  \n \n frappe.msgprint(f\"Somme des jours par ann\u00e9e : {somme_jours_par_annee}\")\n "
        exec(script, {"self": self, "frappe": frappe, "doc": self})

